     1	import { useEffect, useState } from "react";
     2	import { useNN } from "../context/NNProvider";
     3	import Layer from "./Layer";
     4	import React from "react";
     5	import "./main.css";
     6	function NeuralNet({
     7	  neuronsPerLayer,
     8	  setNeuronsPerLayer,
     9	  setActivationsPerLayer,
    10	  setInitializationPerLayer,
    11	  setRegularizationPerLayer,
    12	  maxNeuron,
    13	  disabledActivations,
    14	}) {
    15	  const { layer } = useNN();
    16	  const [connections, setConnections] = useState([]);
    17	
    18	  useEffect(() => {
    19	    const updateConnections = () => {
    20	      const layers = document.querySelectorAll(".lay");
    21	
    22	      if (layers.length < 2) return; // Need at least 2 layers for connections
    23	
    24	      let newConnections = [];
    25	      for (let i = 0; i < layers.length - 1; i++) {
    26	        const currentLayer = layers[i];
    27	        const nextLayer = layers[i + 1];
    28	        const currentNeurons = currentLayer.querySelectorAll(".neuron");
    29	        const nextNeurons = nextLayer.querySelectorAll(".neuron");
    30	
    31	        currentNeurons.forEach((currNeuron) => {
    32	          const currentRect = currNeuron.getBoundingClientRect();
    33	          const containerRect = document
    34	            .querySelector(".container")
    35	            .getBoundingClientRect();
    36	
    37	          // Calculate relative position to the container
    38	          const currentX =
    39	            currentRect.left - containerRect.left + currentRect.width / 2;
    40	          const currentY =
    41	            currentRect.top - containerRect.top + currentRect.height / 2;
    42	
    43	          nextNeurons.forEach((nextNeuron) => {
    44	            const nextRect = nextNeuron.getBoundingClientRect();
    45	
    46	            // Calculate relative position to the container
    47	            const nextX =
    48	              nextRect.left - containerRect.left + nextRect.width / 2;
    49	            const nextY =
    50	              nextRect.top - containerRect.top + nextRect.height / 2;
    51	
    52	            newConnections.push({
    53	              x1: currentX,
    54	              y1: currentY,
    55	              x2: nextX,
    56	              y2: nextY,
    57	            });
    58	          });
    59	        });
    60	      }
    61	
    62	      setConnections(newConnections);
    63	    };
    64	
    65	    // Use a longer timeout to ensure DOM is fully rendered
    66	    const timeoutId = setTimeout(updateConnections, 100);
    67	
    68	    // Also update on window resize and scroll
    69	    const handleResize = () => {
    70	      setTimeout(updateConnections, 100);
    71	    };
    72	
    73	    const handleScroll = () => {
    74	      setTimeout(updateConnections, 50);
    75	    };
    76	
    77	    const container = document.querySelector(".container");
    78	
    79	    window.addEventListener("resize", handleResize);
    80	    if (container) {
    81	      container.addEventListener("scroll", handleScroll);
    82	    }
    83	
    84	    return () => {
    85	      clearTimeout(timeoutId);
    86	      window.removeEventListener("resize", handleResize);
    87	      if (container) {
    88	        container.removeEventListener("scroll", handleScroll);
    89	      }
    90	    };
    91	  }, [maxNeuron, layer, neuronsPerLayer]);
    92	
    93	  return (
    94	    <div className="container">
    95	      <svg className="networksvg">
    96	        {connections.map((line, i) => (
    97	          <line key={i} x1={line.x1} x2={line.x2} y1={line.y1} y2={line.y2} />
    98	        ))}
    99	      </svg>
   100	      {Array.from({ length: layer }, (_, i) => (
   101	        <Layer
   102	          key={i}
   103	          index={i}
   104	          setNeuronsPerLayer={setNeuronsPerLayer}
   105	          setRegularizationPerLayer={setRegularizationPerLayer}
   106	          setActivationsPerLayer={setActivationsPerLayer}
   107	          setInitializationPerLayer={setInitializationPerLayer}
   108	          maxNeuron={maxNeuron}
   109	          disabledActivations={disabledActivations}
   110	        />
   111	      ))}
   112	    </div>
   113	  );
   114	}
